#include <stdio.h>
#include <stdlib.h>

#define MAX_SIGNAL_SIZE 10000 // Adjust this based on the expected size of your signal

int main() {
    FILE *file;
    double signal[MAX_SIGNAL_SIZE];
    int signal_size = 0;

    // Open the file containing the signal data
    file = fopen("signal_data.txt", "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        return 1;
    }

    // Read the signal data from the file
    while (fscanf(file, "%lf", &signal[signal_size]) == 1 && signal_size < MAX_SIGNAL_SIZE) {
        signal_size++;
    }

    // Close the file
    fclose(file);

    // Print the acquired signal data
    printf("Acquired signal data:\n");
    for (int i = 0; i < signal_size; i++) {
        printf("%f ", signal[i]);
    }
    printf("\n");

    return 0;
}
```

